    if m:
        name=m.group(1); rest=m.group(2)
        kws=re.findall(r'`([^`]+)`', rest)
        w=int(m.group(3))
        loads=re.findall(r'`([^`]+\.md)`', m.group(4))
        prose[name]=(w,kws,loads)
for k,v in prose.items():
    cw=S.get(k,{}).get('weight')
    ck=S.get(k,{}).get('keywords')
    cm=M.get(k)
