import re
t=open('ROUTER.md').read()
blocks=re.findall(r'```python\n(.*?)```', t, re.S)
code=blocks[-1].replace('Path(__file__).resolve().parent','Path(".")')
ns={}
exec(compile(code.replace('load(guarded)','pass'),'<r>','exec'), ns)
S=ns['INTENT_SIGNALS']; M=ns['RESOURCE_MAP']; D=ns['DEFAULT_RESOURCES']
print('intents',len(S),'maps',len(M))
prose={}
for line in t.splitlines():
    m=re.match(r'- \*\*`([A-Z_]+)`\*\* fires on (.+?) at weight (\d+)(.*)$', line)
    if m:
        name=m.group(1); rest=m.group(2)
        kws=re.findall(r'`([^`]+)`', rest)
        w=int(m.group(3))
        loads=re.findall(r'`([^`]+\.md)`', m.group(4))
        prose[name]=(w,kws,loads)
print('prose keys match:', sorted(prose)==sorted(S), set(prose)^set(S))
for k,v in prose.items():
    cw=S[k]['weight']; ck=S[k]['keywords']; cm=M.get(k)
    if v[0]!=cw: print(k,'WEIGHT',v[0],cw)
    if set(ck)!=set(v[1]): print(k,'KW', set(v[1])^set(ck))
    if cm!=v[2]: print(k,'MAP',v[2],cm)
print('all files:', sorted(set(sum(M.values(),[])+D)))
EOF

